import numpy as np

class WavySphere:
    def __init__(self, dim=5):
        self.dim = dim

    def f(self, x):
        # Spherical component
        sphere = np.sum(x**2)

        # Wavy component with multiple frequencies
        wavy = 0.0
        for i in range(self.dim):
            wavy += np.sin(5 * x[i]) + 0.5 * np.sin(10 * x[i]) + 0.2 * np.sin(20 * x[i])

        # Combined function with scaling
        return sphere + 0.1 * wavy

import numpy as np

class TwistedBasin:
    def __init__(self, dim=5):
        self.dim = dim

    def f(self, x):
        # Global quadratic basin
        quadratic = np.sum(x**2)

        # Cross-dimensional coupling term with phase shifts
        coupling = 0.0
        for i in range(self.dim):
            for j in range(i+1, self.dim):
                coupling += np.sin(2 * np.pi * (x[i] + x[j]) / 3)

        # Combine terms with different weights
        return quadratic + 5 * coupling
